const { chromium, browserPath } = require('../helpers/browser.cjs');
const fs = require('node:fs'),
  path = require('node:path'),
  assert = require('node:assert/strict');
const out = path.resolve(__dirname, '../../../output/verification/v1.8.0/pet-slots');
const KEY = 'bubble-integrated-v15-machine';
// Fixtures persist a result generated by the actual core. Browser animation never grants rewards.
(async () => {
  const { EndlessGame } = await import('../../src/core/index.mjs');
  const { MemoryStore } = await import('../../src/core/storage.mjs');
  const { startPetSlot } = await import('../../src/core/pet-slots.mjs');
  const { createServer } = await import('../../tools/server.mjs');
  const server = createServer();
  await new Promise((ok, fail) => {
    server.once('error', fail);
    server.listen(4251, '127.0.0.1', ok);
  });
  fs.mkdirSync(out, { recursive: true });
  let browser;
  const report = {
    scenarios: [],
    errors: [],
    fixturePolicy:
      'Real core draws persisted before browser load; no presentation reward simulation.',
  };
  function fixture(type, empty = false) {
    for (let seed = 1; seed < 1000; seed++) {
      const g = new EndlessGame({ seed, petSlotsEnabled: true });
      g.coin({ receiptId: 'qa-slot-' + seed });
      if (empty)
        g.tx((s) => {
          s.content.credit += s.board.filter((b) => b.source === 'system').length;
          s.board = [];
          s.network.id = null;
          s.stage.targetIds = [];
          s.stage.collectedIds = [];
        });
      g.tx((s, emit) => startPetSlot(g, s, emit, 'qa-persisted-spin'));
      if (g.s.petSlots.pending.rewardType === type && (!empty || g.s.petSlots.pending.fallbackFrom))
        return g.exportState();
    }
    throw Error('No fixture for ' + type);
  }
  async function open(saved, suffix, reduced = false) {
    const page = await browser.newPage({
      viewport: { width: 1100, height: 1050 },
      reducedMotion: reduced ? 'reduce' : 'no-preference',
    });
    page.on('pageerror', (e) => report.errors.push({ scenario: suffix, error: e.message }));
    page.on('console', (e) => {
      if (e.type() === 'error') report.errors.push({ scenario: suffix, error: e.text() });
    });
    await page.addInitScript(
      ({ saved, KEY }) => {
        if (!sessionStorage.getItem('qa-fixture')) {
          localStorage.setItem(KEY, JSON.stringify(saved));
          sessionStorage.setItem('qa-fixture', '1');
        }
      },
      { saved, KEY },
    );
    await page.goto('http://127.0.0.1:4251/?test=1');
    await page.waitForFunction(() => window.testGame?.ready);
    await page.locator('aside input[type=checkbox]').last().check();
    return page;
  }
  async function durable(page) {
    return page.evaluate((KEY) => JSON.parse(localStorage.getItem(KEY)), KEY);
  }
  function conservation(s) {
    assert.equal(
      s.ledger.earned,
      Object.values(s.ledger.rewards).reduce((n, r) => n + r.count, 0),
    );
    assert.equal(
      s.ammoBonus.total,
      Object.values(s.ammoBonus.rewards).reduce((n, r) => n + r.count, 0),
    );
    // Full validation is independent of UI counters and includes physical inventory and ammo invariants.
    new EndlessGame({ store: new MemoryStore(s), petSlotsEnabled: true });
    assert.ok(s.ledger.confirmed <= s.ledger.earned);
  }
  try {
    let thirdShot;
    for (let seed = 1; seed < 150 && !thirdShot; seed++) {
      const g = new EndlessGame({ seed });
      g.coin({ receiptId: 'three-real-clears' });
      let passed = true;
      for (let n = 0; n < 2; n++) {
        const move = g
          .opportunities()
          .filter((m) => m.direct.length)
          .sort((a, b) => b.direct.length - a.direct.length)[0];
        if (!move) {
          passed = false;
          break;
        }
        g.setAim(move.angle);
        g.fire();
        for (let f = 0; g.s.projectile && f < 200; f++) g.advance(0.25);
        for (let f = 0; (g.s.cooldown > 0 || g.s.content.flow?.pending) && f < 200; f++)
          g.advance(0.25);
      }
      if (passed && g.s.petSlots.charge === 2 && g.opportunities().some((m) => m.direct.length))
        thirdShot = g.exportState();
    }
    assert.ok(thirdShot, 'must find two genuine clearing shots with a playable third');
    const miss = new EndlessGame({ store: new MemoryStore(thirdShot) }),
      missMove = miss.opportunities().find((m) => m.cell && !m.direct.length);
    assert.ok(missMove, 'fixture must permit an actual attached miss');
    miss.setAim(missMove.angle);
    miss.fire();
    for (let f = 0; miss.s.projectile && f < 200; f++) miss.advance(0.25);
    assert.equal(miss.s.combo.streak, 0);
    assert.equal(miss.s.petSlots.charge, 0);
    const free = new EndlessGame({ seed: 500 });
    free.tx((s) => (s.petSlots.charge = 2));
    free.fire();
    for (let f = 0; free.s.projectile && f < 200; f++) free.advance(0.25);
    assert.equal(free.s.petSlots.charge, 2);
    assert.equal(free.s.combo.streak, 0);
    report.scenarios.push({
      type: 'miss-and-free',
      missResetsCombo: true,
      missClearsUnfinishedCharge: true,
      freeDoesNotCharge: true,
    });
    browser = await chromium.launch({ executablePath: browserPath(), headless: true });
    const three = await open(thirdShot, 'third-real-paid-clear');
    await three.evaluate(() => {
      testGame.bestAim();
      testGame.fire();
    });
    await three.waitForFunction(() => testGame.events().some((e) => e.type === 'petSlotStarted'));
    await three.locator('#cabinet').screenshot({ path: path.join(out, 'third-clear-start.png') });
    assert.equal((await durable(three)).petSlots.charge, 3);
    await three.waitForFunction(() => testGame.events().some((e) => e.type === 'petSlotResolved'));
    const threeState = await durable(three);
    assert.equal(threeState.combo.streak, 3);
    conservation(threeState);
    report.scenarios.push({
      type: 'three-real-paid-clears',
      combo: threeState.combo.streak,
      spin: threeState.petSlots.lastResult.spinId,
    });
    await three.close();
    for (const type of ['tickets', 'lightning', 'specials', 'ammo', 'dual', 'fullClear']) {
      const saved = fixture(type),
        before = structuredClone(saved),
        page = await open(saved, type);
      await page.locator('#cabinet').screenshot({ path: path.join(out, type + '-spinning.png') });
      await page.waitForFunction(() => testGame.snapshot().petSlots?.state === 'charging', null, {
        timeout: 12000,
      });
      const after = await durable(page),
        result = after.petSlots.lastResult;
      assert.equal(result.rewardType, type);
      assert.equal(after.ledger.earned - before.ledger.earned, result.actualTicketDelta);
      assert.equal(after.paidAmmo - before.paidAmmo, result.actualAmmoDelta);
      assert.equal(after.petSlots.charge, 0);
      assert.equal(
        after.combo.streak,
        before.combo.streak,
        'reward does not recursively create a combo',
      );
      if (type === 'tickets') assert.equal(result.actualTicketDelta, result.count);
      if (type === 'ammo') {
        assert.equal(result.actualAmmoDelta, result.count);
        assert.equal(after.ammoBonus.total - before.ammoBonus.total, result.count);
      }
      if (type === 'dual') assert.equal(after.assist.state, 'ready');
      if (type === 'specials') {
        assert.equal(result.added.length, result.count);
        assert.ok(
          result.added.every((b) => after.board.find((a) => a.id === b.id)?.kind === 'bomb'),
        );
        assert.equal(after.board.length, before.board.length);
      }
      if (type === 'lightning' || type === 'fullClear') {
        assert.ok(result.removed.length >= 2);
        assert.ok(result.actualTicketDelta > 0);
        assert.equal(result.actualAmmoDelta, 0, 'slot clear cannot generate big-clear ammo');
      }
      conservation(after);
      await page.waitForTimeout(220);
      await page.locator('#cabinet').screenshot({ path: path.join(out, type + '-resolved.png') });
      await page.waitForFunction(
        () => {
          const s = testGame.stats();
          return (
            !s.feedback.rewardFlights.queued &&
            !s.feedback.rewardFlights.flying &&
            s.scene.displayedPending === testGame.snapshot().tickets.pending
          );
        },
        null,
        { timeout: 25000 },
      );
      const hud = await page.evaluate(() => ({
        flights: testGame.stats().feedback.rewardFlights,
        shown: testGame.stats().scene.displayedPending,
        actual: testGame.snapshot().tickets.pending,
        slot: testGame.upgrade().petSlots,
      }));
      assert.equal(hud.shown, hud.actual);
      const earned = after.ledger.earned,
        bonus = after.ammoBonus.total;
      await page.reload();
      await page.waitForFunction(() => window.testGame?.ready);
      const restored = await durable(page);
      assert.equal(restored.ledger.earned, earned);
      assert.equal(restored.ammoBonus.total, bonus);
      report.scenarios.push({
        type,
        count: result.count,
        ticketDelta: result.actualTicketDelta,
        ammoDelta: result.actualAmmoDelta,
        removed: result.removed.length,
        added: result.added.length,
        hud,
        reloadNoDuplicate: true,
      });
      await page.close();
    }
    const empty = fixture('tickets', true),
      fallback = await open(empty, 'fallback');
    await fallback.waitForFunction(() => testGame.snapshot().petSlots.state === 'charging');
    const result = (await durable(fallback)).petSlots.lastResult;
    assert.equal(result.actualTicketDelta, 12);
    assert.ok(result.fallbackFrom);
    report.scenarios.push({
      type: 'fallback',
      from: result.fallbackFrom,
      tickets: result.actualTicketDelta,
    });
    await fallback.close();
    const pausePage = await open(fixture('ammo'), 'pause-reload-muted-reduced', true);
    await pausePage.locator('#mute').click();
    await pausePage.locator('#pause').click();
    assert.equal(await pausePage.evaluate(() => testGame.audio().enabled), false);
    assert.equal(await pausePage.evaluate(() => testGame.upgrade().petSlots.reduced), true);
    await pausePage.waitForTimeout(100);
    const frozen = await durable(pausePage);
    await pausePage.waitForTimeout(500);
    assert.equal((await durable(pausePage)).petSlots.remaining, frozen.petSlots.remaining);
    await pausePage.reload();
    await pausePage.waitForFunction(() => window.testGame?.ready);
    await pausePage.locator('aside input[type=checkbox]').last().check();
    await pausePage.waitForFunction(() => testGame.snapshot().petSlots.state === 'charging');
    const recovered = await durable(pausePage);
    assert.equal(recovered.petSlots.lastResult.spinId, frozen.petSlots.spinId);
    assert.equal(recovered.ammoBonus.total - frozen.ammoBonus.total, frozen.petSlots.pending.count);
    conservation(recovered);
    report.scenarios.push({
      type: 'pause-reload',
      frozenRemaining: frozen.petSlots.remaining,
      sameSpin: true,
      reducedMotion: true,
      mutedDuringPause: true,
    });
    await pausePage.close();
    const zero = fixture('tickets');
    zero.paidAmmo = 0;
    zero.paidShots = 10;
    const zeroPage = await open(zero, 'zero-ammo-overlay');
    await zeroPage
      .locator('#cabinet')
      .screenshot({ path: path.join(out, 'zero-ammo-spinning.png') });
    await zeroPage.waitForFunction(() => testGame.snapshot().petSlots.state === 'charging');
    assert.equal((await durable(zeroPage)).paidAmmo, 0);
    report.scenarios.push({ type: 'zero-ammo-overlay', screenshot: 'zero-ammo-spinning.png' });
    await zeroPage.close();
    assert.deepEqual(report.errors, []);
    fs.writeFileSync(path.join(out, 'report.json'), JSON.stringify(report, null, 2));
    console.log(JSON.stringify(report, null, 2));
  } finally {
    await browser?.close();
    await new Promise((ok) => server.close(ok));
  }
})().catch((e) => {
  console.error(e);
  process.exitCode = 1;
});
